import { NextRequest } from 'next/server';
import { TABLE_REGISTRY } from '@/lib/tableRegistry';
import { dataGet, dataPost, dataPatch, dataDelete, dataNotFound } from '@/lib/dataRoute';

/* Ai domain data route (GENERATED by the wire closure, 2026-11-15):
   the named API surface for the ai tables that had no hand-written
   route. Tenant-scoped CRUD through the shared handler in
   lib/dataRoute.ts, driven by each table's TABLE_REGISTRY entry.
   Tables served here:
   - ai_ab_assignments
   - ai_ab_tests
   - ai_agents
   - ai_budget_alerts
   - ai_disclosures
   - ai_gateway_requests
   - ai_gateway_settings
   - ai_gateway_usage_monthly
   - ai_intent_events
   - ai_mcp_connections
   - ai_purposes
   - ai_tasks
*/

const SERVED = new Set([
  'ai_ab_assignments',
  'ai_ab_tests',
  'ai_agents',
  'ai_budget_alerts',
  'ai_disclosures',
  'ai_gateway_requests',
  'ai_gateway_settings',
  'ai_gateway_usage_monthly',
  'ai_intent_events',
  'ai_mcp_connections',
  'ai_purposes',
  'ai_tasks'
]);

function entry(table: string) {
  return SERVED.has(table) ? TABLE_REGISTRY[table] ?? null : null;
}

export async function GET(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataGet(req, table, r) : dataNotFound(table);
}

export async function POST(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPost(req, table, r) : dataNotFound(table);
}

export async function PATCH(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPatch(req, table, r) : dataNotFound(table);
}

export async function DELETE(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataDelete(req, table, r) : dataNotFound(table);
}
